def loadModule(moduleName: str, scriptPath: Path) -> ModuleType:
    if scriptPath.name == STANDALONE_RENDERER_FILE_NAME:
        compressedSource = base64.b64decode(EMBEDDED_STANDALONE_SOURCE_BASE64)
        embeddedSource = zlib.decompress(compressedSource).decode("utf-8")
        sourceModule = ModuleType(moduleName)
        sourceModule.__file__ = str(SCRIPT_DIRECTORY / STANDALONE_RENDERER_FILE_NAME)
        sys.modules[moduleName] = sourceModule
        exec(compile(embeddedSource, sourceModule.__file__, "exec"), sourceModule.__dict__)
        return sourceModule
    moduleSpec = importlib.util.spec_from_file_location(moduleName, scriptPath)
    if moduleSpec is None or moduleSpec.loader is None:
        raise ImportError(f"Unable to load plotting module: {scriptPath}")
    sourceModule = importlib.util.module_from_spec(moduleSpec)
    sys.modules[moduleName] = sourceModule
    moduleSpec.loader.exec_module(sourceModule)
    return sourceModule


def replaceGradientLabel(textValue: str) -> str:
    if textValue == "EC gradient 1 (z)":
        return textValue
    return (
        textValue.replace("EC principal gradient", "EC gradient 2")
        .replace("G1", "G2")
        .replace("gradient 1", "gradient 2")
    )


