def patchRowThreeModule(rowThreeModule: ModuleType) -> None:
    def loadG2Inputs(analysisRoot: Path) -> dict[str, object]:
        networkLongFrame = pd.read_csv(
            RESULT_DIRECTORY / "Yeo7_network_level_G1G2_long.csv"
        )
        networkLongFrame["g1_net"] = networkLongFrame["g2_net"]
        networkMainEffectFrame = pd.read_csv(
            RESULT_DIRECTORY
            / "GLM_Yeo7_network_G1G2_main_effect_splitFDR_G2_network.csv"
        )
        if set(networkMainEffectFrame["item"]) != set(rowThreeModule.NETWORK_ORDER):
            raise ValueError(
                "The G2 network main-effect table must contain all seven Yeo networks."
            )
        return {
            "networkLongFrame": networkLongFrame,
            "networkMainEffectFrame": networkMainEffectFrame,
            "networkLabelFrame": pd.read_csv(
                INPUT_DIRECTORY / "Schaefer400_7Yeo_network_labels_with_ID.csv"
            ),
        }

    rowThreeModule.loadRowThreeInputs = loadG2Inputs

    originalRenderPanelGBrainAssets = rowThreeModule.renderPanelGBrainAssets

    def renderPanelGBrainAssetsWithPointOneMaximum(
        outputDirectory: Path,
        networkLabelFrame: pd.DataFrame,
        networkMainEffectFrame: pd.DataFrame,
    ) -> dict[str, Path]:
        betaColorLimit = 0.05
        scaledMainEffectFrame = networkMainEffectFrame.copy()

        # BrainSpace independently normalizes each rendered surface. Each
        # single-network surface contains only one finite p value, so that
        # value otherwise lands at the same end of the colormap regardless
        # of its actual magnitude. Remap the renderer's local 0–1 range back
        # to the requested global FDR range before selecting colors.
        originalPlotSurf = rowThreeModule.plot_surf
        globalPValueColormap = matplotlib.colormaps[rowThreeModule.BETA_CMAP]

        def plotSurfWithGlobalPValueColors(*plotArguments, **plotKeywordArguments):
            surfaceMapping = plotArguments[0]
            arrayName = plotKeywordArguments["array_name"]
            plottedSurface = next(iter(surfaceMapping.values()))
            plottedValues = np.asarray(plottedSurface.PointData[arrayName], dtype=float)
            finiteValues = plottedValues[np.isfinite(plottedValues)]
            if finiteValues.size == 0:
                return originalPlotSurf(*plotArguments, **plotKeywordArguments)

            localMinimum = float(np.min(finiteValues))
            localMaximum = float(np.max(finiteValues))
            if np.isclose(localMinimum, localMaximum):
                constantColor = globalPValueColormap(
                    (localMinimum + betaColorLimit) / (2.0 * betaColorLimit)
                )
                remappedColormap = ListedColormap([constantColor, constantColor])
            else:
                globalPositions = np.linspace(localMinimum, localMaximum, 256)
                remappedColormap = ListedColormap(
                    globalPValueColormap(
                        (globalPositions + betaColorLimit)
                        / (2.0 * betaColorLimit)
                    )
                )
            plotKeywordArguments["cmap"] = remappedColormap
            plotKeywordArguments["color_range"] = None
            return originalPlotSurf(*plotArguments, **plotKeywordArguments)

        rowThreeModule.plot_surf = plotSurfWithGlobalPValueColors
        try:
            panelGBrainPaths = originalRenderPanelGBrainAssets(
                outputDirectory,
                networkLabelFrame,
                scaledMainEffectFrame,
            )
        finally:
            rowThreeModule.plot_surf = originalPlotSurf

        normalizedBetaByNetwork = np.clip(
            (
                scaledMainEffectFrame.set_index("item")["beta"].astype(float)
                + betaColorLimit
            )
            / (2.0 * betaColorLimit),
            0.0,
            1.0,
        ).to_dict()
        networkMasksByView: dict[str, dict[str, np.ndarray]] = {
            "lateral": {},
            "medial": {},
        }

        for networkName in rowThreeModule.NETWORK_ORDER:
            targetRgb = np.asarray(
                globalPValueColormap(normalizedBetaByNetwork[networkName])[:3]
            ) * 255.0
            for viewName in ("lateral", "medial"):
                brainPath = panelGBrainPaths[f"{networkName}_{viewName}"]
                brainRgb = np.asarray(Image.open(brainPath).convert("RGB"))
                channelRange = np.ptp(brainRgb.astype(float), axis=2)
                coloredMask = channelRange > 18.0
                networkMasksByView[viewName][networkName] = coloredMask

                coloredLuminance = (
                    brainRgb[..., 0] * 0.2126
                    + brainRgb[..., 1] * 0.7152
                    + brainRgb[..., 2] * 0.0722
                )[coloredMask]
                medianLuminance = float(np.median(coloredLuminance))
                shadingScale = np.ones(coloredMask.shape, dtype=float)
                shadingScale[coloredMask] = np.clip(
                    coloredLuminance / max(medianLuminance, 1.0),
                    0.50,
                    1.45,
                )
                recoloredRgb = brainRgb.copy()
                recoloredRgb[coloredMask] = np.clip(
                    targetRgb[None, :] * shadingScale[coloredMask, None],
                    0.0,
                    255.0,
                ).astype(np.uint8)
                Image.fromarray(recoloredRgb).save(brainPath)

        # Rebuild the all-network views from the seven recolored maps so every
        # parcel uses exactly the same global p-value-to-color conversion.
        for viewName in ("lateral", "medial"):
            allNetworkPath = panelGBrainPaths[f"All_{viewName}"]
            allNetworkRgb = np.asarray(
                Image.open(allNetworkPath).convert("RGB")
            ).copy()
            for networkName in rowThreeModule.NETWORK_ORDER:
                networkPath = panelGBrainPaths[f"{networkName}_{viewName}"]
                networkRgb = np.asarray(Image.open(networkPath).convert("RGB"))
                coloredMask = networkMasksByView[viewName][networkName]
                allNetworkRgb[coloredMask] = networkRgb[coloredMask]
            Image.fromarray(allNetworkRgb).save(allNetworkPath)

        return panelGBrainPaths

    rowThreeModule.renderPanelGBrainAssets = (
        renderPanelGBrainAssetsWithPointOneMaximum
    )

    originalDrawPanelG = rowThreeModule.drawPanelG

    def drawPanelGWithPointOneColorbar(
        figure,
        subplotSpec,
        brainPaths: dict[str, Path],
    ) -> None:
        originalDrawPanelG(figure, subplotSpec, brainPaths)
        colorbarAxes = [
            childAxis
            for parentAxis in figure.axes
            for childAxis in parentAxis.child_axes
            if childAxis.get_xlabel()
            in {"FDR-corrected p value", "Group main-effect β"}
        ]
        if len(colorbarAxes) != 1:
            raise RuntimeError(
                "Unable to identify the panel-f beta colorbar axis."
            )
        colorbarAxis = colorbarAxes[0]
        colorbarAxis.set_xlim(-0.05, 0.05)
        colorbarAxis.set_xticks([-0.05, 0.0, 0.05])
        colorbarAxis.set_xticklabels(["−0.05", "0", "0.05"])

    rowThreeModule.drawPanelG = drawPanelGWithPointOneColorbar


def patchSourceLoader(combinedModule: ModuleType) -> None:
    originalLoadSourceModule = combinedModule.loadSourceModule

    def loadG2SourceModule(moduleName: str, scriptPath: Path) -> ModuleType:
        sourceModule = originalLoadSourceModule(moduleName, scriptPath)
        if moduleName == "gradientAnalysisRowOne":
            patchRowOneModule(sourceModule)
        elif moduleName == "gradientAnalysisRowTwo":
            patchRowTwoModule(sourceModule)
        elif moduleName == "gradientAnalysisRowThree":
            patchRowThreeModule(sourceModule)
        return sourceModule

    combinedModule.loadSourceModule = loadG2SourceModule


def patchRowOneBrainAssetPipeline(combinedModule: ModuleType) -> None:
    """Use native G2 names for panel-b data keys and rendered assets."""

    def getG2RowOneBrainPaths(
        rowOneModule: ModuleType,
        outputDirectory: Path,
        rowOneInputs: dict[str, object],
        ecGroupMeanZ: dict[str, dict[str, np.ndarray]],
        refreshAssets: bool,
    ) -> dict[str, Path]:
        assetDirectory = outputDirectory / "brainspace-assets"
        existingPaths = {
            "YEO7": assetDirectory / "yeo7-network-two-views.png",
            "ASD_G2": assetDirectory / "asd-g2-ec-gradient.png",
            "HC_G2": assetDirectory / "hc-g2-ec-gradient.png",
        }
        if refreshAssets or not all(path.exists() for path in existingPaths.values()):
            return rowOneModule.renderBrainSurfaceAssets(
                outputDirectory,
                rowOneInputs["networkLabelFrame"],
                ecGroupMeanZ,
            )
        return existingPaths

    combinedModule.getRowOneBrainPaths = getG2RowOneBrainPaths


def patchPrecomputedGroupMeans(combinedModule: ModuleType) -> None:
    """Load saved group-mean maps instead of z-scoring subject matrices."""

    precomputedGroupMeans = {
        groupName: {
            gradientName: np.load(
                GROUP_MEAN_DIRECTORY
                / f"{gradientName}_{groupName}_group_mean_z.npy"
            )
            for gradientName in ("G1", "G2")
        }
        for groupName in ("ASD", "HC")
    }
    for groupName, gradientMaps in precomputedGroupMeans.items():
        for gradientName, groupMeanMap in gradientMaps.items():
            if groupMeanMap.shape != (400,):
                raise ValueError(
                    f"Saved {gradientName} {groupName} group-mean map must "
                    f"contain 400 ROI values; found {groupMeanMap.shape}."
                )
            if not np.isfinite(groupMeanMap).all():
                raise ValueError(
                    f"Saved {gradientName} {groupName} group-mean map "
                    "contains non-finite values."
                )

    def loadPrecomputedGroupMeans(
        networkLongFrame,
        g1Matrix: np.ndarray,
        g2Matrix: np.ndarray | None = None,
    ) -> dict[str, dict[str, np.ndarray]]:
        del networkLongFrame, g1Matrix
        requestedGradients = ("G1", "G2") if g2Matrix is not None else ("G2",)
        return {
            groupName: {
                gradientName: precomputedGroupMeans[groupName][gradientName]
                for gradientName in requestedGradients
            }
            for groupName in ("ASD", "HC")
        }

    combinedModule.calculateEcGroupMeans = loadPrecomputedGroupMeans

    def loadStandalonePrecomputedGroupMeans(
        analysisRoot: Path,
        gradientNames: tuple[str, ...],
    ) -> dict[str, dict[str, np.ndarray]]:
        del analysisRoot
        requestedGradientNames = set(gradientNames)
        requestedGradientNames.add("G2")
        return {
            groupName: {
                gradientName: precomputedGroupMeans[groupName][gradientName]
                for gradientName in requestedGradientNames
            }
            for groupName in ("ASD", "HC")
        }

    combinedModule.loadPrecomputedGroupMeans = loadStandalonePrecomputedGroupMeans

    def loadDiscardedPanelDPlaceholder(
        analysisRoot: Path,
        rowTwoModule: ModuleType,
    ) -> pd.DataFrame:
        del analysisRoot, rowTwoModule
        return pd.DataFrame(
            {
                "EC_G1": precomputedGroupMeans["HC"]["G1"],
                "FC_G1": precomputedGroupMeans["ASD"]["G1"],
            }
        )

    # The calibrated six-panel layout removes the standalone renderer's
    # temporary correlation panel before export; a finite placeholder lets
    # that base figure be constructed without unrelated EC/FC map files.
    combinedModule.loadCombinedEcFcGroupMeanMap = loadDiscardedPanelDPlaceholder


def patchDynamicAnnotations(combinedModule: ModuleType) -> None:
    originalShiftUniqueText = combinedModule.shiftUniqueText

    def shiftG2AwareText(
        figure,
        textValue: str,
        horizontalShiftPoints: float,
        verticalShiftPoints: float,
    ) -> None:
        matchingTextValue = textValue
        if textValue == "EC gradient 1 (subject-wise whole-brain z-score)":
            matchingTextValue = "EC gradient 2 (subject-wise whole-brain z-score)"
        if textValue.startswith(("HC separation =", "ASD separation =")):
            groupPrefix = textValue.split(" separation", maxsplit=1)[0]
            matchingValues = [
                textObject.get_text()
                for textObject in figure.findobj(
                    match=lambda figureObject: isinstance(
                        figureObject,
                        matplotlib.text.Text,
                    )
                )
                if textObject.get_text().startswith(f"{groupPrefix} separation =")
            ]
            if len(matchingValues) == 1:
                matchingTextValue = matchingValues[0]
        originalShiftUniqueText(
            figure,
            matchingTextValue,
            horizontalShiftPoints,
            verticalShiftPoints,
        )

    combinedModule.shiftUniqueText = shiftG2AwareText


def patchRowTwoPlotWidths(combinedModule: ModuleType) -> None:
    originalShiftAxesHorizontally = combinedModule.shiftAxesHorizontally
    originalShiftYAxisTickLabels = combinedModule.shiftYAxisTickLabels

    def shiftAxesWithPanelDScaling(
        axes: list,
        horizontalShiftPoints: float,
    ) -> None:
        panelDPlotAxes = [
            plotAxis
            for plotAxis in axes
            if plotAxis.get_ylabel() == "FC G1 vs EC G1 Spearman ρ"
        ]
        for plotAxis in panelDPlotAxes:
            originalPosition = plotAxis.get_position()
            scaledWidth = originalPosition.width * PANEL_D_PLOT_WIDTH_SCALE
            plotAxis.set_position(
                [
                    originalPosition.x0
                    + (originalPosition.width - scaledWidth) / 2,
                    originalPosition.y0,
                    scaledWidth,
                    originalPosition.height,
                ]
            )
        originalShiftAxesHorizontally(axes, horizontalShiftPoints)

    combinedModule.shiftAxesHorizontally = shiftAxesWithPanelDScaling

    def keepNarrowPanelTickLabelsAdjacent(
        plotAxis,
        horizontalShiftPoints: float,
        verticalShiftPoints: float = 0.0,
    ) -> None:
        isPanelDOrEAxis = (
            plotAxis.get_ylabel()
            in {"FC G1 vs EC G1 Spearman ρ", "G1 separation (z)"}
            or (
                plotAxis.get_ylabel() == "Percentage (%)"
                and plotAxis.get_xlabel() == "G1 separation (z)"
            )
        )
        if isPanelDOrEAxis:
            horizontalShiftPoints = 0.0
        originalShiftYAxisTickLabels(
            plotAxis,
            horizontalShiftPoints,
            verticalShiftPoints,
        )

    combinedModule.shiftYAxisTickLabels = keepNarrowPanelTickLabelsAdjacent


def updateFigureLabelsToG2(figure) -> None:
    for plotAxis in figure.axes:
        yAxisLabel = plotAxis.get_ylabel()
        isPanelEHistogramAxis = (
            yAxisLabel == "Percentage (%)"
            and plotAxis.get_xlabel() == "G1 separation (z)"
        )
        isAdjustedRowTwoAxis = yAxisLabel in {
            "FC G1 vs EC G1 Spearman ρ",
            "G1 separation (z)",
        } or isPanelEHistogramAxis

        if isAdjustedRowTwoAxis:
            plotAxis.minorticks_off()
            standardTickTransform = plotAxis.get_yaxis_transform(which="tick1")
            for tickObject in plotAxis.yaxis.get_major_ticks():
                tickObject.label1.set_transform(standardTickTransform)
                tickObject.label1.set_x(0.0)
                tickObject.label1.set_horizontalalignment("right")
                tickObject.label2.set_visible(False)
            standardXTickTransform = plotAxis.get_xaxis_transform(which="tick1")
            for tickObject in plotAxis.xaxis.get_major_ticks():
                tickObject.label1.set_transform(standardXTickTransform)
                tickObject.label1.set_y(0.0)
                tickObject.label1.set_horizontalalignment("center")
                tickObject.label2.set_visible(False)

        if yAxisLabel == "FC G1 vs EC G1 Spearman ρ":
            plotAxis.set_yticks([0.4, 0.5, 0.6, 0.7, 0.8, 0.9])
            plotAxis.yaxis.set_label_coords(-0.30, 0.5)
            plotAxis.yaxis.label.set_fontsize(16)
        elif yAxisLabel == "G1 separation (z)":
            plotAxis.set_yticks([0.0, 0.2, 0.4, 0.6])
            plotAxis.yaxis.set_label_coords(-0.38, 0.5)
            for textObject in plotAxis.findobj(
                match=lambda figureObject: isinstance(
                    figureObject,
                    matplotlib.text.Text,
                )
            ):
                normalizedTickText = textObject.get_text().replace("−", "-")
                if normalizedTickText in {"0.5", "-0.5"}:
                    textObject.set_visible(False)
        elif isPanelEHistogramAxis:
            plotAxis.set_yticks([0, 10, 20, 30, 40])
            plotAxis.yaxis.set_label_coords(-0.32, 0.5)

        if isAdjustedRowTwoAxis and yAxisLabel != "FC G1 vs EC G1 Spearman ρ":
            plotAxis.yaxis.label.set_fontsize(20)

    for textObject in figure.findobj(
        match=lambda figureObject: isinstance(
            figureObject,
            matplotlib.text.Text,
        )
    ):
        originalText = textObject.get_text()
        updatedText = replaceGradientLabel(originalText)
        updatedText = {
            "Yeo-7 organization along EC gradient 2": (
                "Yeo-7 organization along positive EC gradient 2"
            ),
            "EC gradient 2 (subject-wise whole-brain z-score)": (
                "positive EC gradient 2 (subject-wise whole-brain z-score)"
            ),
        }.get(updatedText, updatedText)
        if updatedText != originalText:
            textObject.set_text(updatedText)


def transformAxesGroup(
    axes: list,
    targetBounds: tuple[float, float, float, float],
) -> None:
    sourcePositions = [plotAxis.get_position() for plotAxis in axes]
    sourceLeft = min(position.x0 for position in sourcePositions)
    sourceBottom = min(position.y0 for position in sourcePositions)
    sourceRight = max(position.x1 for position in sourcePositions)
    sourceTop = max(position.y1 for position in sourcePositions)
    sourceWidth = sourceRight - sourceLeft
    sourceHeight = sourceTop - sourceBottom
    targetLeft, targetBottom, targetRight, targetTop = targetBounds
    targetWidth = targetRight - targetLeft
    targetHeight = targetTop - targetBottom

    for plotAxis, originalPosition in zip(axes, sourcePositions):
        normalizedLeft = (originalPosition.x0 - sourceLeft) / sourceWidth
        normalizedBottom = (originalPosition.y0 - sourceBottom) / sourceHeight
        normalizedWidth = originalPosition.width / sourceWidth
        normalizedHeight = originalPosition.height / sourceHeight
        plotAxis.set_axes_locator(None)
        plotAxis.set_position(
            [
                targetLeft + normalizedLeft * targetWidth,
                targetBottom + normalizedBottom * targetHeight,
                normalizedWidth * targetWidth,
                normalizedHeight * targetHeight,
            ]
        )


def loadNegativeG1SeparationInputs(
    resultDirectory: Path,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    hierarchyFrame = pd.read_csv(
        resultDirectory / "负向连接_Yeo7_hierarchy_distances_G1G2.csv"
    )
    requiredColumns = {"sub_id", "Group", "G1_Default_dist_VisSomMot"}
    missingColumns = requiredColumns - set(hierarchyFrame.columns)
    if missingColumns:
        raise ValueError(
            "Negative-connection G1 separation data are missing columns: "
            + ", ".join(sorted(missingColumns))
        )
    hierarchyGlmFrame = pd.read_csv(
        resultDirectory
        / "负向连接_GLM_hierarchy_distances_G1G2_main_effect_splitFDR_G1_distance.csv"
    )
    return hierarchyFrame, hierarchyGlmFrame


def addNegativeG1SeparationPanel(
    figure,
    rowTwoModule: ModuleType,
    resultDirectory: Path,
    panelBounds: tuple[float, float, float, float],
    panelLabel: str,
    panelTitle: str,
) -> list:
    hierarchyFrame, hierarchyGlmFrame = loadNegativeG1SeparationInputs(
        resultDirectory
    )
    left, bottom, right, top = panelBounds
    panelGrid = figure.add_gridspec(
        1,
        1,
        left=left,
        right=right,
        bottom=bottom,
        top=top,
    )
    existingAxisCount = len(figure.axes)
    rowTwoModule.drawPanelE(
        figure,
        panelGrid[0, 0],
        hierarchyFrame,
        hierarchyGlmFrame,
    )
    panelAxes = figure.axes[existingAxisCount:]
    rowTwoModule.scalePlotAxesWidths(
        [plotAxis for plotAxis in panelAxes if plotAxis.has_data()],
        PANEL_E_PLOT_WIDTH_SCALE,
    )
    for plotAxis in panelAxes:
        if plotAxis.has_data():
            plotAxis.tick_params(axis="y", pad=10)
            plotAxis.tick_params(axis="x", pad=6)
        for textObject in plotAxis.texts:
            if textObject.get_text() == "e":
                textObject.set_text(panelLabel)
            elif textObject.get_text() == "Default–Vis/SomMot G1 separation":
                textObject.set_text(panelTitle)
    return panelAxes


def applyReferenceSixPanelLayout(
    figure,
    rowTwoModule: ModuleType,
) -> None:
    topLevelAxes = list(figure.axes)
    childAxes = [
        childAxis
        for parentAxis in topLevelAxes
        for childAxis in parentAxis.child_axes
    ]

    rowOneAxes = []
    panelEAxes = []
    panelGAxes = []
    axesToRemove = []
    for plotAxis in topLevelAxes:
        position = plotAxis.get_position()
        centerX = (position.x0 + position.x1) / 2
        centerY = (position.y0 + position.y1) / 2
        if centerY > 0.70:
            rowOneAxes.append(plotAxis)
        elif 0.40 < centerY <= 0.70 and centerX > 0.55:
            panelEAxes.append(plotAxis)
        elif centerY <= 0.45 and centerX > 0.50:
            panelGAxes.append(plotAxis)
        else:
            axesToRemove.append(plotAxis)

    if not rowOneAxes or not panelEAxes or not panelGAxes:
        raise RuntimeError(
            "Unable to identify all retained panels for the reference layout."
        )

    for plotAxis in axesToRemove:
        figure.delaxes(plotAxis)

    retainedAxes = set(rowOneAxes + panelEAxes + panelGAxes)
    panelGChildAxes = [
        childAxis
        for childAxis in childAxes
        if any(
            childAxis in parentAxis.child_axes
            for parentAxis in panelGAxes
        )
    ]
    retainedChildAxes = [
        childAxis
        for childAxis in childAxes
        if any(
            childAxis in parentAxis.child_axes
            for parentAxis in retainedAxes
        )
    ]

    transformAxesGroup(rowOneAxes, (0.035, 0.700, 0.975, 0.995))
    transformAxesGroup(panelEAxes, (0.02, 0.355, 0.315, 0.625))
    for plotAxis in panelEAxes:
        if plotAxis.has_data():
            plotAxis.tick_params(axis="y", pad=10)
            plotAxis.tick_params(axis="x", pad=6)
    transformAxesGroup(
        panelGAxes + panelGChildAxes,
        (0.03, 0.035, 0.975, 0.285),
    )

    for colorbarAxis in panelGChildAxes:
        if colorbarAxis.get_xlabel() == "FDR-corrected p value":
            colorbarAxis.set_xlim(0.0, 0.1)
            colorbarAxis.set_xticks([0.0, 0.05, 0.1])
            colorbarAxis.set_xticklabels(["0", "0.05", "0.1"])
            standardTickTransform = colorbarAxis.get_xaxis_transform(
                which="tick1"
            )
            for tickObject in colorbarAxis.xaxis.get_major_ticks():
                tickObject.label1.set_transform(standardTickTransform)
                tickObject.label1.set_y(0.0)
                tickObject.label1.set_horizontalalignment("center")
                tickObject.label2.set_visible(False)

    for childAxis in retainedChildAxes:
        childAxis.set_visible(True)

    for textObject in figure.findobj(
        match=lambda figureObject: isinstance(
            figureObject,
            matplotlib.text.Text,
        )
    ):
        if textObject.get_text() == "e":
            textObject.set_text("c")
        elif textObject.get_text() == "g":
            textObject.set_text("f")
        elif textObject.get_text() == "Yeo-7 network group main-effect p values":
            textObject.set_text(
                "positive EC gradient 2 Yeo-7 network group main-effect β values"
            )
        elif textObject.get_text() == "Yeo-7 network group main-effect β values":
            textObject.set_text(
                "positive EC gradient 2 Yeo-7 network group main-effect β values"
            )

    figure.set_size_inches(
        CANVAS_WIDTH_PIXELS / RASTER_EXPORT_DPI,
        CANVAS_HEIGHT_PIXELS / RASTER_EXPORT_DPI,
        forward=True,
    )

    rowTwoModule.PLOT_AXIS_HEIGHT_INCHES = 2.75
    addNegativeG1SeparationPanel(
        figure,
        rowTwoModule,
        ABIDE1_NEGATIVE_DIRECTORY,
        (0.345, 0.355, 0.655, 0.625),
        "d",
        "",
    )
    addNegativeG1SeparationPanel(
        figure,
        rowTwoModule,
        ABIDE2_NEGATIVE_DIRECTORY,
        (0.68, 0.355, 0.985, 0.625),
        "e",
        "",
    )


