def applyUniformTypographyAndPanelCSpacing(figure) -> None:
    for textObject in figure.findobj(
        match=lambda figureObject: isinstance(
            figureObject,
            matplotlib.text.Text,
        )
    ):
        textObject.set_fontfamily("Arial")
        textObject.set_fontsize(UNIFORM_FONT_SIZE_POINTS)
        if textObject.get_text().strip() in BOLD_PANEL_TITLE_TEXTS:
            textObject.set_fontweight("bold")

    separationPanelAxes = [
        plotAxis
        for plotAxis in figure.axes
        if plotAxis.get_ylabel()
        in {"G1 separation (z)", "G2 separation (z)", "Percentage (%)"}
        and plotAxis.has_data()
    ]
    if len(separationPanelAxes) != 6:
        raise RuntimeError(
            "Unable to identify all six separation plot axes for alignment."
        )

    for plotAxis in separationPanelAxes:
        plotAxis.yaxis.labelpad = 14
        plotAxis.yaxis.label.set_verticalalignment("center")
        plotAxis.yaxis.label.set_horizontalalignment("center")

    histogramAxes = [
        plotAxis
        for plotAxis in separationPanelAxes
        if plotAxis.get_ylabel() == "Percentage (%)"
    ]
    if len(histogramAxes) != 3:
        raise RuntimeError("Unable to identify all three histogram axes.")
    for histogramAxis in histogramAxes:
        histogramLegend = histogramAxis.get_legend()
        if histogramLegend is None:
            raise RuntimeError("A separation histogram legend is missing.")
        histogramLegend.remove()
        histogramAxis.legend(
            loc="upper left",
            bbox_to_anchor=(0.38, 0.88),
            frameon=False,
            fontsize=UNIFORM_FONT_SIZE_POINTS,
            handlelength=1.4,
            labelspacing=0.5,
            handletextpad=0.6,
        )
        histogramAxis.xaxis.label.set_x(0.5)
        histogramAxis.xaxis.label.set_horizontalalignment("center")

    figure.canvas.draw()


def pValueStars(pValue: float) -> str:
    if pValue < 0.001:
        return "***"
    if pValue < 0.01:
        return "**"
    if pValue < 0.05:
        return "*"
    return "n.s."


def applyPanelFGlobalPValueColors(figure) -> None:
    """Apply one fixed symmetric beta color scale to every panel-f brain map."""
    networkMainEffectFrame = pd.read_csv(
        RESULT_DIRECTORY
        / "GLM_Yeo7_network_G1G2_main_effect_splitFDR_G2_network.csv"
    )
    betaColorLimit = 0.05
    normalizedBetaByNetwork = np.clip(
        (networkMainEffectFrame.set_index("item")["beta"].astype(float) + betaColorLimit)
        / (2.0 * betaColorLimit),
        0.0,
        1.0,
    ).to_dict()
    globalPValueColormap = matplotlib.colormaps["RdBu_r"]
    panelImageAxes = [
        plotAxis
        for plotAxis in figure.axes
        if plotAxis.images and plotAxis.get_position().y0 < 0.31
    ]
    if len(panelImageAxes) != 16:
        raise RuntimeError(
            f"Expected 16 panel-f brain image axes; found {len(panelImageAxes)}."
        )

    recoloredArraysByView: dict[int, list[tuple[np.ndarray, np.ndarray]]] = {
        0: [],
        1: [],
    }
    for networkIndex, networkName in enumerate(
        ("Vis", "SomMot", "DorsAttn", "SalVentAttn", "Limbic", "Cont", "Default")
    ):
        targetRgb = np.asarray(
            globalPValueColormap(normalizedBetaByNetwork[networkName])[:3]
        ) * 255.0
        for viewIndex in (0, 1):
            plotAxis = panelImageAxes[networkIndex * 2 + viewIndex]
            brainRgb = np.asarray(plotAxis.images[0].get_array())[..., :3]
            if np.issubdtype(brainRgb.dtype, np.floating) and brainRgb.max() <= 1.0:
                brainRgb = brainRgb * 255.0
            brainRgb = brainRgb.astype(np.uint8)
            coloredMask = np.ptp(brainRgb.astype(float), axis=2) > 18.0
            coloredLuminance = (
                brainRgb[..., 0] * 0.2126
                + brainRgb[..., 1] * 0.7152
                + brainRgb[..., 2] * 0.0722
            )[coloredMask]
            medianLuminance = float(np.median(coloredLuminance))
            shadingScale = np.clip(
                coloredLuminance / max(medianLuminance, 1.0),
                0.50,
                1.45,
            )
            recoloredRgb = brainRgb.copy()
            recoloredRgb[coloredMask] = np.clip(
                targetRgb[None, :] * shadingScale[:, None],
                0.0,
                255.0,
            ).astype(np.uint8)
            plotAxis.images[0].set_data(recoloredRgb)
            recoloredArraysByView[viewIndex].append((recoloredRgb, coloredMask))

    for viewIndex in (0, 1):
        allNetworkAxis = panelImageAxes[14 + viewIndex]
        allNetworkRgb = np.asarray(allNetworkAxis.images[0].get_array())[..., :3]
        if np.issubdtype(allNetworkRgb.dtype, np.floating) and allNetworkRgb.max() <= 1.0:
            allNetworkRgb = allNetworkRgb * 255.0
        allNetworkRgb = allNetworkRgb.astype(np.uint8).copy()
        for recoloredRgb, coloredMask in recoloredArraysByView[viewIndex]:
            allNetworkRgb[coloredMask] = recoloredRgb[coloredMask]
        allNetworkAxis.images[0].set_data(allNetworkRgb)


def drawSeparationPairFromResults(
    figure,
    groupAxisBounds: tuple[float, float, float, float],
    histogramAxisBounds: tuple[float, float, float, float],
    hierarchyFrame: pd.DataFrame,
    valueColumn: str,
    displayGradientName: str,
    adjustedPValue: float,
) -> None:
    groupColors = {"HC": "#8FB1D0", "ASD": "#F0A089"}
    groupAxis = figure.add_axes(groupAxisBounds)
    histogramAxis = figure.add_axes(histogramAxisBounds)
    deterministicRandom = np.random.default_rng(20260803)
    groupValues = []

    for groupIndex, groupName in enumerate(("HC", "ASD")):
        values = hierarchyFrame.loc[
            hierarchyFrame["Group"].eq(groupName), valueColumn
        ].dropna().to_numpy(dtype=float)
        groupValues.append(values)
        violinParts = groupAxis.violinplot(
            values,
            positions=[groupIndex],
            widths=0.76,
            showmeans=False,
            showmedians=False,
            showextrema=False,
        )
        for violinBody in violinParts["bodies"]:
            violinBody.set_facecolor(groupColors[groupName])
            violinBody.set_edgecolor(groupColors[groupName])
            violinBody.set_alpha(0.35)
            violinBody.set_linewidth(0.8)
        jitteredX = groupIndex + deterministicRandom.normal(0.0, 0.045, len(values))
        groupAxis.scatter(
            jitteredX,
            values,
            s=4,
            color=groupColors[groupName],
            alpha=0.30,
            linewidths=0,
            rasterized=True,
        )

    boxPlot = groupAxis.boxplot(
        groupValues,
        positions=[0, 1],
        widths=0.22,
        patch_artist=True,
        showfliers=False,
        medianprops={"color": "#666666", "linewidth": 1.0},
        whiskerprops={"color": "#777777", "linewidth": 0.8},
        capprops={"color": "#777777", "linewidth": 0.8},
    )
    for boxPatch in boxPlot["boxes"]:
        boxPatch.set_facecolor("white")
        boxPatch.set_alpha(0.55)
        boxPatch.set_edgecolor("#777777")
        boxPatch.set_linewidth(0.8)

    combinedValues = np.concatenate(groupValues)
    dataMinimum = min(0.0, float(np.nanmin(combinedValues)))
    dataMaximum = float(np.nanmax(combinedValues))
    dataRange = max(dataMaximum - dataMinimum, 0.1)
    yMaximum = dataMaximum + 0.18 * dataRange
    groupAxis.set_ylim(dataMinimum - 0.02 * dataRange, yMaximum)
    bracketY = dataMaximum + 0.08 * dataRange
    bracketHeight = 0.025 * dataRange
    groupAxis.plot(
        [0, 0, 1, 1],
        [bracketY, bracketY + bracketHeight, bracketY + bracketHeight, bracketY],
        color="#777777",
        linewidth=0.8,
        clip_on=False,
    )
    groupAxis.text(
        0.5,
        bracketY + bracketHeight * 1.25,
        pValueStars(adjustedPValue),
        ha="center",
        va="bottom",
        fontsize=13,
        fontweight="bold",
    )
    groupAxis.set_xticks([0, 1], ["HC", "ASD"])
    groupAxis.set_ylabel(f"{displayGradientName} separation (z)")

    binEdges = np.linspace(dataMinimum, dataMaximum, 8)
    densityGrid = np.linspace(dataMinimum, dataMaximum, 250)
    for groupName, values in zip(("HC", "ASD"), groupValues):
        weights = np.full(len(values), 100.0 / len(values))
        histogramAxis.hist(
            values,
            bins=binEdges,
            weights=weights,
            color=groupColors[groupName],
            edgecolor="#777777",
            linewidth=0.6,
            alpha=0.25,
            label=groupName,
        )
        if len(np.unique(values)) > 1:
            kernelDensity = gaussian_kde(values)
            binWidth = binEdges[1] - binEdges[0]
            densityPercentage = kernelDensity(densityGrid) * binWidth * 100.0
            histogramAxis.plot(
                densityGrid,
                densityPercentage,
                color=groupColors[groupName],
                linewidth=1.1,
            )
        histogramAxis.axvline(
            float(np.mean(values)),
            color=groupColors[groupName],
            linestyle=(0, (2, 1)),
            linewidth=0.8,
            alpha=0.8,
        )
    histogramAxis.set_xlabel(f"{displayGradientName} separation (z)")
    histogramAxis.set_ylabel("Percentage (%)")
    if displayGradientName == "G2":
        histogramAxis.set_xticks([0.0, 0.5])
        histogramAxis.set_xticklabels(["0", "0.5"])
    histogramAxis.legend(loc="upper right", frameon=False, fontsize=12)

    for plotAxis in (groupAxis, histogramAxis):
        plotAxis.spines["top"].set_visible(False)
        plotAxis.spines["right"].set_visible(False)
        plotAxis.tick_params(labelsize=12, width=0.8, length=3)
        plotAxis.xaxis.label.set_fontsize(12)
        plotAxis.yaxis.label.set_fontsize(12)


